B.aLN=new A.iI("Kabul Edilebilir Kullan\u0131m",null)
B.aKp=new A.il("Uygulamay\u0131 yaln\u0131zca ki\u015fisel mekan analizi ama\xe7l\u0131 kullanabilirsiniz. A\u015fa\u011f\u0131daki davran\u0131\u015flar yasakt\u0131r:",null)
