B.aIW=new A.tI("Biraz yak\u0131n \xe7ek","Oda \xe7ok uzaktan g\xf6r\xfcnd\xfc\u011f\xfc i\xe7in detaylar k\xfc\xe7\xfck kal\u0131yor. Bir-iki ad\u0131m yakla\u015f\u0131rsan AI mobilyalar\u0131 daha iyi tan\u0131r.")
B.aIX=new A.tI("Daha iyi sonu\xe7 i\xe7in","Daha net bir a\xe7\u0131 \xe7ekersen restyle \xe7ok daha g\xfczel \xe7\u0131kacak. Yine de devam edebilirsin.")
B.aIY=new A.tI("Kadrajda insanlar var","Foto\u011frafa odaklanabilelim diye odan\u0131n bo\u015f halini \xe7ekersen \xe7ok yard\u0131m\u0131 dokunur. Kediyi \xe7\u0131karmana gerek yok \ud83d\ude0a")
B.aIZ=new A.tI("Foto biraz bulan\u0131k","Daha net bir kare \xe7ekersen, AI mobilyalar\u0131 ve oranlar\u0131 \xe7ok daha iyi anlar. \u0130ki saniye sabit tut yeter.")
B.aJ_=new A.tI("\xc7\xf6z\xfcn\xfcrl\xfck d\xfc\u015f\xfck","Foto \xe7ok k\xfc\xe7\xfck geldi. Galerinden b\xfcy\xfck orijinaliyle y\xfckleyebilir misin?")
B.aJ0=new A.tI("Burada \u0131\u015f\u0131k az","Perdeyi a\xe7\u0131p ya da lambay\u0131 yak\u0131p tekrar dener misin? Ayd\u0131nl\u0131k karelerde renk analizi ger\xe7e\u011fine yak\u0131n \xe7\u0131k\u0131yor.")
